/**
 * PWA runtime (web build only): service-worker registration, update prompt and the install prompt.
 * The service worker itself (dist/sw.js) is generated by Workbox at build time (scripts/build-web.mjs)
 * and only precaches the app shell and static assets — never API responses, trips or sessions.
 */
import { useSyncExternalStore } from 'react';
import { BASE_PATH } from '@/config';

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

interface PwaState {
  updateReady: boolean;
  canInstall: boolean;
  installed: boolean;
  offlineReady: boolean;
}

let state: PwaState = { updateReady: false, canInstall: false, installed: false, offlineReady: false };
let waiting: ServiceWorker | null = null;
let installEvent: BeforeInstallPromptEvent | null = null;
const listeners = new Set<() => void>();
const set = (patch: Partial<PwaState>) => {
  state = { ...state, ...patch };
  listeners.forEach((l) => l());
};

export const isStandalone = (): boolean =>
  typeof window !== 'undefined' && (window.matchMedia?.('(display-mode: standalone)').matches || (navigator as { standalone?: boolean }).standalone === true);

export const isIos = (): boolean => typeof navigator !== 'undefined' && /iphone|ipad|ipod/i.test(navigator.userAgent);

let started = false;
export function startPwa(): void {
  if (started || typeof window === 'undefined') return;
  started = true;
  set({ installed: isStandalone() });

  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    installEvent = e as BeforeInstallPromptEvent;
    set({ canInstall: true });
  });
  window.addEventListener('appinstalled', () => {
    installEvent = null;
    set({ canInstall: false, installed: true });
  });

  // The service worker exists only in production builds (`npm run build:web`), not in `expo start`.
  if (__DEV__ || !('serviceWorker' in navigator)) return;
  // Expo Router evaluates the root layout lazily, often after `load` has already fired.
  const register = () => {
    navigator.serviceWorker
      .register(`${BASE_PATH}/sw.js`, { scope: `${BASE_PATH}/` })
      .then((reg) => {
        const track = (sw: ServiceWorker | null) => {
          sw?.addEventListener('statechange', () => {
            if (sw.state === 'installed') {
              if (navigator.serviceWorker.controller) {
                waiting = sw;
                set({ updateReady: true });
              } else set({ offlineReady: true });
            }
          });
        };
        if (reg.waiting && navigator.serviceWorker.controller) {
          waiting = reg.waiting;
          set({ updateReady: true });
        }
        if (reg.active) set({ offlineReady: true });
        reg.addEventListener('updatefound', () => track(reg.installing));
      })
      .catch(() => undefined);
    let reloading = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (reloading) return;
      reloading = true;
      window.location.reload();
    });
  };
  if (document.readyState === 'complete') register();
  else window.addEventListener('load', register, { once: true });
}

/** Activates the waiting service worker; the page reloads into the new version. */
export function applyUpdate(): void {
  waiting?.postMessage({ type: 'SKIP_WAITING' });
}

export async function promptInstall(): Promise<boolean> {
  if (!installEvent) return false;
  await installEvent.prompt();
  const { outcome } = await installEvent.userChoice;
  installEvent = null;
  set({ canInstall: false });
  return outcome === 'accepted';
}

export function usePwa(): PwaState {
  return useSyncExternalStore(
    (l) => {
      listeners.add(l);
      return () => listeners.delete(l);
    },
    () => state,
    () => state,
  );
}
